const fs = require('fs');
const path = require('path');
const http = require('http');

const ENDPOINT = 'http://127.0.0.1:54418/status';
const OUT_DIR = path.join(__dirname, 'results');
const OUT_FILE = path.join(OUT_DIR, 'status.json');

function fetchStatus(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      const { statusCode } = res;
      res.resume();
      res.on('end', () => resolve(statusCode));
      res.on('error', reject);
    }).on('error', reject);
  });
}

async function main() {
  const status = await fetchStatus(ENDPOINT);
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_FILE, JSON.stringify({ status }, null, 2));
  console.log(`wrote ${OUT_FILE} with status=${status}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

